//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05328.xml";
scwin.gLastJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//저장버튼 클릭 시
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(txb_FILE) == '') {
        $c.win.alert("[첨부파일]을 선택하세요.");
        file.focus();
        return;
    }
    //데이터 중복 체크
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        for (var j = 1; j <= dts_List.getTotalRow(); j++) {
            if (i == j) continue;
            if ((dts_List.getCellData(i, "ISU_SRT_CD") == dts_List.getCellData(j, "ISU_SRT_CD")) &&
                (dts_List.getCellData(i, "BAS_DD") == dts_List.getCellData(j, "BAS_DD"))) {
                $c.win.alert(i + "항목과 " + j + "항목이 동일값 입니다.\n기준일 " + dts_List.getCellData(i, "BAS_DD") + ", 종목단축코드 " + dts_List.getCellData(i, "ISU_SRT_CD"));
                return;
            }
        }
    }
    if (confirm('저장 하시겠습니까?')) {
        //setObjectValue(txb_acpt_ddtm,"");
        scwin.gLastJob = "저장";
        // SynthEtfTrctptInfo
        trs_Save.Action = "/SectionTypeChange.do?method=insVentBzExcelFile&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.Post();
    }
};




// 저장 에러 발생 시
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};





//파일첨부 버튼 클릭 시
scwin.fn_SelectAttach = function() {
    var vFile = file.getValue();
    if (vFile == "" || txb_FILE.getValue() == vFile) {
        return;
    } else if (vFile.substring(vFile.length - 3, vFile.length).toUpperCase() != "XLS") {
        $c.win.alert("엑셀파일(*.xls)만 입력하시기 바랍니다.");
        txb_FILE.setValue("");
        return;
    } else {
        dts_List.removeAll();
        txb_FILE.setValue(file.getValue());
        dts_FileList.setCellData(1, "fileInfo", file.getValue());
        dts_FileList.setCellData(1, "fileUrl", file.getValue());
    }
    //엑셀 파일 불러오기
    scwin.fn_LoadExcel();
};


// 초기화
scwin.fn_Init = function() {
    //파일업로드 데이터셋 초기화

    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
};


//엑셀파일 데이터 읽기
scwin.fn_LoadExcel = function() {
    trs_Save.Action = "/SectionTypeChange.do?method=readVentBzExcelFile&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(O:pOutput=dts_List,I:pFile=dts_FileList)";
    trs_Save.Post();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    if ((trs_Save.ErrorMsg).indexOf('50014') != -1) {
        $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else {
        $c.win.alert(trs_Save.ErrorMsg);
        //alert_error2(trs_Save);

    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.gLastJob == "저장") {
        var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        $c.win.alert(msg);
        //var fr_fn_Search = frame.Provider("../").fn_list_sync;
        //fr_fn_Search();	
        //frame.CloseFrame();

    }
};
scwin.btn_FORM_U1_onclick = function() {
    location.href = "/lstproc/kosdaq_ventbz_sample.xls";
};
scwin.gform_onload = function() {
    frame.width = 990;
    frame.height = 680;
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_Init();
};
scwin.file_OnClick = function() {
    scwin.gLastJob = "엑셀데이터 불러오기";
    scwin.fn_SelectAttach();
};
